const rows = $json.results || [];

let question = "";
try {
  question = $("Build Logistics Query").first().json.question || "";
} catch (e) {
  question = "";
}

const logisticsItems = rows.map((row) => ({
  item_id: row.item_id || null,
  item_type: row.item_type || null,
  item_name: row.item_name || null,
  properties: row.properties || {},
  relationship: row.relationship || null,
  connected_labels: row.connected_labels || [],
  connected_entity: row.connected_entity || null,
}));

return [
  {
    json: {
      agent: "logistics_specialist",
      domain: "Logistics Specialist",
      status: "data_retrieved",
      question,
      evidenceLabel: "logisticsItems",
      evidenceData: logisticsItems,
      rawResult: $json,
    },
  },
];

const agent = $json.agent || "logistics_specialist";
const domain = $json.domain || "Logistics Specialist";
const question = $json.question || "";
const evidenceLabel = $json.evidenceLabel || "logisticsItems";
const evidenceData = $json.evidenceData || [];
const rawResult = $json.rawResult || {};

const systemPrompt = `
You are a Logistics Specialist Agent for a supply chain knowledge graph.

Your job:
- Analyze location, transport, freight, route, and delivery-related graph data.
- Identify logistics dependencies, route exposure, connected entities, and delivery bottlenecks.
- Explain the operational impact clearly.
- Give practical logistics recommendations.
- Do not invent facts.
- If the graph data is limited, clearly say that.

Return ONLY valid JSON.
`;

const userPrompt = `
User question:
${question}

Logistics evidence:
${JSON.stringify(evidenceData, null, 2)}

Raw graph result:
${JSON.stringify(rawResult, null, 2)}

Return JSON with this exact schema:
{
  "answer": "string",
  "keyFindings": ["string"],
  "logisticsInsights": [
    {
      "id": "string",
      "type": "string",
      "name": "string",
      "insight": "string"
    }
  ],
  "routeInsights": [
    {
      "route": "string",
      "impact": "string"
    }
  ],
  "recommendations": ["string"],
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      agent,
      domain,
      question,
      evidenceLabel,
      evidenceData,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.2,
        max_tokens: 2048,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The logistics specialist could not generate a summary.",
    keyFindings: [],
    logisticsInsights: [],
    routeInsights: [],
    recommendations: [],
    confidence: "low",
  };
}

let context = {};
try {
  context = $("Build LLM Summary Payload").first().json;
} catch (e) {
  context = {};
}

return [
  {
    json: {
      agent: "logistics_specialist",
      domain: "Logistics Specialist",
      status: "completed",
      question: context.question || "",
      answer: parsed.answer || "",
      keyFindings: parsed.keyFindings || [],
      logisticsInsights: parsed.logisticsInsights || [],
      routeInsights: parsed.routeInsights || [],
      recommendations: parsed.recommendations || [],
      confidence: parsed.confidence || "medium",
      evidence: {
        logisticsItems: context.evidenceData || [],
      },
      rawLlmOutput: parsed,
    },
  },
];

const selectedAgents = $json.selectedAgents || [];

const shouldRun =
  selectedAgents.includes("logistics_specialist") ||
  selectedAgents.includes("all");

return [
  {
    json: {
      ...$json,
      shouldRun,
    },
  },
];

return [
  {
    json: {
      agent: "logistics_specialist",
      domain: "Logistics Specialist",
      status: "skipped",
      question: $json.question || "",
      answer: "",
      keyFindings: [],
      logisticsInsights: [],
      routeInsights: [],
      recommendations: [],
      confidence: "not_applicable",
      evidence: {},
    },
  },
];
